contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking inputs to exercise approval and a specific log call
    function run(address logger, address keepAddress, bytes32 digest, bytes32 r, bytes32 s, bytes32 txid) public payable {
        require(logger != address(0), "logger cannot be zero");
        // Initially, the logger may or may not be approved. We'll observe behavior in both cases.
        // We will call logCreated and logGotRedemptionSignature and logRedeemed as representatives.

        // First, from this contract (which is msg.sender for calls) ensure approved status for 'logger' equals false by default
        // We cannot change c._contractOwner, but the constructor deployer of c is the checker; however we can use c.setApprovedLogger only if this contract is owner. We don't know that, so we will instead observe behavior for this contract's msg.sender (InvMutTest).
        // The rule we assert uses the observable approvedToLog for this contract's address and ties it to return values of log* calls.

        bool beforeApproved = c.approvedToLog(address(this));

        // Call three logging functions and capture whether they revert or returned true/false
        bool r1;
        bool r2;
        bool r3;
        // logCreated
        try c.logCreated(keepAddress) returns (bool v1) { r1 = v1; } catch { r1 = false; }
        // logGotRedemptionSignature
        try c.logGotRedemptionSignature(digest, r, s) returns (bool v2) { r2 = v2; } catch { r2 = false; }
        // logRedeemed
        try c.logRedeemed(txid) returns (bool v3) { r3 = v3; } catch { r3 = false; }

        // General rule: for this contract's address, all logging functions behave consistently with approvedToLog(address(this)):
        // If approvedToLog is true then each log call must have returned true (and not reverted). If approvedToLog is false then each log call must have returned false (either by returning false or by reverting — but contract implementation returns false without revert).
        assert(
            (beforeApproved && r1 && r2 && r3) || (!beforeApproved && (!r1) && (!r2) && (!r3))
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking selector to choose which log function to call
    // 0 = logCreated(address)
    // 1 = logRedemptionRequested(address,bytes32,uint256,bytes,uint256,bytes)
    // 2 = logGotRedemptionSignature(bytes32,bytes32,bytes32)
    // 3 = logRegisteredPubkey(bytes32,bytes32)
    // 4 = logSetupFailed()
    // 5 = logFraudDuringSetup()
    // 6 = logFunded()
    // 7 = logCourtesyCalled()
    // 8 = logStartedLiquidation(bool)
    // 9 = logRedeemed(bytes32)
    // 10 = logLiquidated()
    // 11 = logExitedCourtesyCall()
    function run(uint8 selector,
                 address a1,
                 bytes32 b1,
                 bytes32 b2,
                 uint256 n1,
                 bytes calldata bs1,
                 uint256 n2,
                 bytes calldata bs2,
                 bool flag)
        public payable
    {
        require(selector <= 11, "invalid selector");

        // observe approved status for this contract (msg.sender will be this test contract when calling c)
        bool beforeApproved = c.approvedToLog(address(this));
        bool callReturned;
        bool didRevert = false;

        // Make exactly one state-changing call to c based on selector
        if (selector == 0) {
            try c.logCreated(a1) returns (bool r) { callReturned = r; } catch { didRevert = true; callReturned = false; }
        } else if (selector == 1) {
            try c.logRedemptionRequested(a1, b1, n1, bs1, n2, bs2) returns (bool r) { callReturned = r; } catch { didRevert = true; callReturned = false; }
        } else if (selector == 2) {
            try c.logGotRedemptionSignature(b1, b2, b1) returns (bool r) { callReturned = r; } catch { didRevert = true; callReturned = false; }
        } else if (selector == 3) {
            try c.logRegisteredPubkey(b1, b2) returns (bool r) { callReturned = r; } catch { didRevert = true; callReturned = false; }
        } else if (selector == 4) {
            try c.logSetupFailed() returns (bool r) { callReturned = r; } catch { didRevert = true; callReturned = false; }
        } else if (selector == 5) {
            try c.logFraudDuringSetup() returns (bool r) { callReturned = r; } catch { didRevert = true; callReturned = false; }
        } else if (selector == 6) {
            try c.logFunded() returns (bool r) { callReturned = r; } catch { didRevert = true; callReturned = false; }
        } else if (selector == 7) {
            try c.logCourtesyCalled() returns (bool r) { callReturned = r; } catch { didRevert = true; callReturned = false; }
        } else if (selector == 8) {
            try c.logStartedLiquidation(flag) returns (bool r) { callReturned = r; } catch { didRevert = true; callReturned = false; }
        } else if (selector == 9) {
            try c.logRedeemed(b1) returns (bool r) { callReturned = r; } catch { didRevert = true; callReturned = false; }
        } else if (selector == 10) {
            try c.logLiquidated() returns (bool r) { callReturned = r; } catch { didRevert = true; callReturned = false; }
        } else { // 11
            try c.logExitedCourtesyCall() returns (bool r) { callReturned = r; } catch { didRevert = true; callReturned = false; }
        }

        // read approved status after the call
        bool afterApproved = c.approvedToLog(address(this));

        // General rule asserted: the logging calls must not mutate the approvedLoggers mapping
        // and must return exactly the pre-call approved status when they do not revert.
        // If the call reverted, we allow callReturned==false but still require mapping unchanged.
        assert(afterApproved == beforeApproved && (didRevert || callReturned == beforeApproved));
    }

    // allow receiving ETH if needed by future variants (not used here)
    receive() external payable {}
}

