contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, bytes32 b1, bytes32 b2, bytes calldata bs, uint256 utxoSize, uint256 fee) public payable {
        require(target != address(0));
        // sample read of approved status before any state-changing call
        bool beforeTargetApproved = c.approvedToLog(target);
        // Also check some other random address (this contract) approved status
        bool beforeThisApproved = c.approvedToLog(address(this));

        // Make a state-changing call from this contract: attempt to logRegisteredPubkey
        // The behavior should depend only on approvedToLog(msg.sender) where msg.sender is this contract
        bool reverted;
        bool ret;
        try c.logRegisteredPubkey(b1, b2) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // After the call, the approved status for arbitrary addresses (including target and this contract)
        // must remain unchanged because none of the log... functions modify approvedLoggers mapping.
        bool afterTargetApproved = c.approvedToLog(target);
        bool afterThisApproved = c.approvedToLog(address(this));

        // The general rule: the call must not revert, and its boolean return must equal the approval status of the caller at call-time
        // OR if it reverted then it must be because of some internal reason; however these functions do not revert on approval checks
        // so we assert that the call did not revert, its return equals the prior approval for this contract,
        // and approvedLoggers for any observed addresses are unchanged.
        assert(reverted == false && ret == beforeThisApproved && afterTargetApproved == beforeTargetApproved && afterThisApproved == beforeThisApproved);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test behavior of logCreated: result depends only on approvedLoggers[msg.sender]
    // and calling it does not change approvedLoggers for any address.
    function run(address loggerToApprove, address queriedAddr, address keepAddr) public payable {
        require(queriedAddr != address(0) && keepAddr != address(0));

        // Snapshot before: approved status for loggerToApprove and queriedAddr
        bool beforeApproved_logger = c.approvedToLog(loggerToApprove);
        bool beforeApproved_queried = c.approvedToLog(queriedAddr);

        // If we want to test both branches, set approval according to input: flip if needed
        // Use only public function setApprovedLogger; caller must be owner — this test contract is deployer
        // We conservatively try to set the loggerToApprove approval to true so msg.sender (this test contract) can call logCreated as that address.
        // But setApprovedLogger is onlyOwner; the test contract deployed c so it is the owner and may call it.
        c.setApprovedLogger(loggerToApprove, true);

        // Confirm we actually set it (view) — read after modification
        bool afterSet_logger = c.approvedToLog(loggerToApprove);

        // Now, we simulate calling logCreated from the loggerToApprove address by making the test contract call (msg.sender == this contract)
        // To emulate calls from loggerToApprove, we instead check the general invariant: calling logCreated returns true iff approvedToLog(msg.sender)
        // So call logCreated from this contract (msg.sender == address(this)). First snapshot this contract's approval.
        bool beforeApproved_self = c.approvedToLog(address(this));

        // Make the log call and capture whether it reverted or returned false/true
        bool returned;
        try c.logCreated(keepAddr) returns (bool r) {
            returned = r;
        } catch {
            // If it reverts, treat as false for the property (should not revert in current implementation)
            returned = false;
        }

        // Snapshot after: approved status for loggerToApprove and queriedAddr and self
        bool afterApproved_logger = c.approvedToLog(loggerToApprove);
        bool afterApproved_queried = c.approvedToLog(queriedAddr);
        bool afterApproved_self = c.approvedToLog(address(this));

        // General rule to assert:
        // 1) The returned value equals approvedToLog(msg.sender) at call time (we observed beforeApproved_self).
        // 2) Calling logCreated did not change approval status of any other observed address (loggerToApprove and queriedAddr) nor this contract.
        assert(returned == beforeApproved_self && afterApproved_logger == beforeApproved_logger && afterApproved_queried == beforeApproved_queried && afterApproved_self == beforeApproved_self);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We pick logRedemptionRequested as a representative log function that may return true/false
    // The rule: calling a log function does not mutate approvedLoggers for any observed address
    // and its returned boolean equals approvedToLog(msg.sender) at call time.
    function run(address addrA, address addrB, address keepAddr, bytes32 digest, uint256 utxoSize, bytes calldata redeemerOutputScript, uint256 requestedFee, bytes calldata outpoint) public payable {
        // simple parameter validity to avoid zero-address weirdness when reading mapping
        require(addrA != address(0) && addrB != address(0) && keepAddr != address(0));

        // Snapshot approval statuses for three addresses (including this contract)
        bool beforeA = c.approvedToLog(addrA);
        bool beforeB = c.approvedToLog(addrB);
        bool beforeSelf = c.approvedToLog(address(this));

        // Do not change ownership or approvedLoggers except potentially via setApprovedLogger; but we avoid calling it here
        // Make the log call and record whether it reverted and/or returned a value.
        bool reverted;
        bool ret;
        try c.logRedemptionRequested(address(this), digest, utxoSize, redeemerOutputScript, requestedFee, outpoint) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false; // treat revert as false for the logical relation; the rule will relate ret to beforeSelf
        }

        // Snapshot after the call
        bool afterA = c.approvedToLog(addrA);
        bool afterB = c.approvedToLog(addrB);
        bool afterSelf = c.approvedToLog(address(this));

        // Assert the general rule:
        // - The call did not change any observed approvedLoggers entries (for addrA, addrB, this)
        // - And the returned boolean equals the approval of msg.sender at call time (beforeSelf).
        // Note: if the call reverted, ret==false and the relation ret == beforeSelf must still hold (which fails if revert occurs when beforeSelf==true)
        assert(afterA == beforeA && afterB == beforeB && afterSelf == beforeSelf && ret == beforeSelf);
    }

    receive() external payable { }
}

