        // We'll sample three addresses: the logger under test, this contract, and an arbitrary other (tx.origin)
        // Note: tx.origin is externally visible; using it as a different address to observe.
        bool before_target = c.approvedLoggers(logger);
        bool before_self = c.approvedLoggers(address(this));
        bool before_origin = c.approvedLoggers(tx.origin);

