        require(true);
        // record contract balance before any operations
        uint256 balBefore = address(c).balance;

        // Ensure this contract is NOT approved initially: call a logging function and observe it returns false
        bool reverted;
        bool ret1;
        try c.logCreated(keepAddr) returns (bool v) { reverted = false; ret1 = v; } catch { reverted = true; ret1 = false; }

        // Now set this contract as approved by calling setApprovedLogger via c (onlyOwner required).
        // The InvMutTest deployed c, so it is the owner; call setApprovedLogger to approve this contract as logger.
        // This is a state-changing call that must be top-level.
        c.setApprovedLogger(address(this), true);

        // After approval, calls should return true. Call several log functions and record returns.
        bool retCreated = c.logCreated(keepAddr);
        bool retRedemptionRequested = c.logRedemptionRequested(requester, digest, utxoSize, redeemerOutputScript, requestedFee, outpoint);
        bool retGotSig = c.logGotRedemptionSignature(digest, r, s);
        bool retRegistered = c.logRegisteredPubkey(pubX, pubY);
        bool retSetupFailed = c.logSetupFailed();
        bool retFraud = c.logFraudDuringSetup();
        bool retFunded = c.logFunded();
        bool retCourtesy = c.logCourtesyCalled();
        bool retStartedLiquidation = c.logStartedLiquidation(wasFraud);
        bool retRedeemed = c.logRedeemed(txid);
        bool retLiquidated = c.logLiquidated();
        bool retExited = c.logExitedCourtesyCall();

        // read balance after calls
        uint256 balAfter = address(c).balance;

