        // (1) the first unauthorised call ret1 must have been false or reverted, and
        // (2) after approval all subsequent log...() calls returned true, and
        // (3) none of these logging calls changed the contract's Ether balance (balBefore == balAfter).
        assert(((!reverted && ret1 == false) || (reverted && ret1 == false))
            && retCreated && retRedemptionRequested && retGotSig && retRegistered && retSetupFailed && retFraud && retFunded && retCourtesy && retStartedLiquidation && retRedeemed && retLiquidated && retExited
            && balBefore == balAfter);
    }

